sp_widget.client_script:
api.controller = function() {

    var c = this;


    c.selectedStudent = '';

    c.selectedEvent = '';

    c.loading = false;

    c.sendingRequest = false;


    /* =========================================
       FIND MATCHES
       ========================================= */

    c.loadMatches = function() {

        if (!c.selectedStudent ||
            !c.selectedStudent.trim()) {

            alert(
                'Please enter your name.'
            );

            return;
        }


        if (!c.selectedEvent) {

            alert(
                'Please select an event.'
            );

            return;
        }


        c.loading = true;


        c.server.get({

            action: 'find_matches',

            selectedStudent:
                c.selectedStudent.trim(),

            selectedEvent:
                c.selectedEvent

        }).then(function(response) {

            c.loading = false;

            var result =
                response.data || {};

            c.data.matches =
                result.matches || [];

            c.data.message =
                result.message || '';

            c.data.selectedEventName =
                result.selectedEventName || '';

        }, function(error) {

            c.loading = false;

            console.log(
                'FIND MATCH ERROR:',
                error
            );

            alert(
                'Unable to find teammates. Please try again.'
            );

        });

    };


    /* =========================================
       ENTER KEY
       ========================================= */

    c.handleStudentKeypress = function(event) {

        if (event.which === 13) {

            c.loadMatches();

        }

    };


    /* =========================================
       SEND TEAM REQUEST
       ========================================= */

    c.sendTeamRequest = function(match) {

        if (c.sendingRequest) {
            return;
        }


        if (!match ||
            !match.studentId) {

            alert(
                'Unable to identify the selected student.'
            );

            return;
        }


        if (!c.selectedEvent) {

            alert(
                'Please select an event.'
            );

            return;
        }


        c.sendingRequest = true;


        c.server.get({

            action:
                'send_team_request',

            receiverStudent:
                match.studentId,

            eventId:
                c.selectedEvent

        }).then(function(response) {

            c.sendingRequest = false;

            var result =
                response.data || {};


            if (result.success === true) {

                alert(
                    'Team request sent successfully.'
                );

                /*
                 * Go to My Team Requests.
                 * The selected student will now be able
                 * to see the request.
                 */

                window.location.href =
                    '?id=my_team_requests';

            } else {

                alert(
                    result.message ||
                    'Unable to send the team request.'
                );

            }

        }, function(error) {

            c.sendingRequest = false;

            console.log(
                'SEND TEAM REQUEST ERROR:',
                error
            );

            alert(
                'Unable to send the team request.'
            );

        });

    };

};

sp_widget.css:
/* =========================================================
   CAMPUS CONNECT - FIND TEAMMATES
   COMPLETE STANDALONE CSS
   ========================================================= */

.cc-teammate-page {
    min-height: 100vh;
    padding: 32px 0 0 180px;
    background: transparent;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI",
                 Roboto, Arial, sans-serif;
    box-sizing: border-box;
}

.cc-teammate-page *,
.cc-teammate-page *::before,
.cc-teammate-page *::after {
    box-sizing: border-box;
}


/* =========================================================
   HERO
   ========================================================= */

.cc-teammate-hero {
    width: 100%;
    max-width: 1180px;
    margin: 0 auto 28px;
    padding: 30px 34px;
    border-radius: 18px;
    background: linear-gradient(
        135deg,
        #173f73 0%,
        #1f5d9b 55%,
        #2877b9 100%
    );
    display: flex;
    align-items: center;
    gap: 22px;
    box-shadow: 0 12px 30px rgba(23, 63, 115, 0.16);
}

.cc-hero-icon {
    width: 62px;
    height: 62px;
    min-width: 62px;
    border-radius: 16px;
    background: rgba(255, 255, 255, 0.16);
    color: #ffffff;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 30px;
    font-weight: 600;
}

.cc-hero-content h1 {
    margin: 0;
    color: #ffffff;
    font-size: 30px;
    line-height: 1.2;
    font-weight: 700;
}

.cc-hero-content p {
    margin: 8px 0 0;
    color: rgba(255, 255, 255, 0.84);
    font-size: 15px;
    line-height: 1.5;
}


/* =========================================================
   SELECTION CARD
   ========================================================= */

.cc-selection-card {
    width: 100%;
    max-width: 1180px;
    margin: 0 auto 28px;
    padding: 28px;
    background: #ffffff;
    border: 1px solid #e5eaf1;
    border-radius: 16px;
    box-shadow: 0 6px 20px rgba(31, 45, 61, 0.07);
}

.cc-selection-header {
    display: flex;
    align-items: center;
    gap: 16px;
    margin-bottom: 24px;
}

.cc-selection-icon {
    width: 48px;
    height: 48px;
    min-width: 48px;
    border-radius: 12px;
    background: #edf5ff;
    color: #1f5d9b;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 23px;
}

.cc-selection-header h2 {
    margin: 0;
    color: #1f2937;
    font-size: 21px;
    font-weight: 700;
}

.cc-selection-header p {
    margin: 5px 0 0;
    color: #718096;
    font-size: 14px;
    line-height: 1.5;
}


/* =========================================================
   FORM
   ========================================================= */

.cc-form-group {
    width: 100%;
}

.cc-label {
    display: block;
    margin-bottom: 8px;
    color: #344054;
    font-size: 14px;
    font-weight: 600;
}

.cc-select {
    width: 100%;
    height: 46px;
    padding: 0 14px;
    border: 1px solid #d4dce7;
    border-radius: 9px;
    background: #ffffff;
    color: #243b53;
    font-size: 14px;
    outline: none;
    transition: all 0.2s ease;
}

.cc-select::placeholder {
    color: #98a2b3;
}

.cc-select:focus {
    border-color: #2877b9;
    box-shadow: 0 0 0 3px rgba(40, 119, 185, 0.12);
}

select.cc-select {
    cursor: pointer;
}


/* =========================================================
   PRIMARY BUTTON
   ========================================================= */

.cc-send-request-btn {
    min-height: 44px;
    padding: 0 22px;
    border: none;
    border-radius: 9px;
    background: #1f5d9b;
    color: #ffffff;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition:
        background 0.2s ease,
        transform 0.2s ease,
        box-shadow 0.2s ease;
}

.cc-send-request-btn:hover:not(:disabled) {
    background: #174d84;
    transform: translateY(-1px);
    box-shadow: 0 6px 15px rgba(31, 93, 155, 0.22);
}

.cc-send-request-btn:active:not(:disabled) {
    transform: translateY(0);
}

.cc-send-request-btn:disabled {
    opacity: 0.55;
    cursor: not-allowed;
}


/* =========================================================
   INFORMATION MESSAGE
   ========================================================= */

.cc-info-message {
    width: 100%;
    max-width: 1180px;
    margin: 0 auto 24px;
    padding: 15px 18px;
    border: 1px solid #d9e6f5;
    border-radius: 10px;
    background: #f3f8fd;
    color: #35516e;
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 14px;
}

.cc-message-icon {
    font-size: 18px;
    color: #2877b9;
}


/* =========================================================
   LOADING
   ========================================================= */

.cc-loading-card {
    width: 100%;
    max-width: 1180px;
    margin: 0 auto 28px;
    padding: 22px 24px;
    background: #ffffff;
    border: 1px solid #e5eaf1;
    border-radius: 14px;
    display: flex;
    align-items: center;
    gap: 16px;
    box-shadow: 0 5px 18px rgba(31, 45, 61, 0.06);
}

.cc-loading-icon {
    width: 42px;
    height: 42px;
    min-width: 42px;
    border-radius: 50%;
    background: #edf5ff;
    color: #1f5d9b;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 22px;
    animation: cc-teammate-spin 1s linear infinite;
}

.cc-loading-card strong {
    display: block;
    color: #25364a;
    font-size: 15px;
}

.cc-loading-card p {
    margin: 4px 0 0;
    color: #7b8794;
    font-size: 13px;
}

@keyframes cc-teammate-spin {
    from {
        transform: rotate(0deg);
    }

    to {
        transform: rotate(360deg);
    }
}


/* =========================================================
   RESULTS
   ========================================================= */

.cc-results-section {
    width: 100%;
    max-width: 1180px;
    margin: 0 auto;
}

.cc-results-header {
    margin-bottom: 18px;
    padding: 0 2px;
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 20px;
}

.cc-results-header h2 {
    margin: 0;
    color: #1f2937;
    font-size: 22px;
    font-weight: 700;
}

.cc-results-header p {
    margin: 5px 0 0;
    color: #7b8794;
    font-size: 14px;
}

.cc-match-count {
    padding: 7px 13px;
    border-radius: 20px;
    background: #edf5ff;
    color: #1f5d9b;
    font-size: 13px;
    font-weight: 700;
    white-space: nowrap;
}


/* =========================================================
   MATCH CARD
   ========================================================= */

.cc-match-card {
    margin-bottom: 20px;
    overflow: hidden;
    background: #ffffff;
    border: 1px solid #e3e8ef;
    border-radius: 15px;
    box-shadow: 0 5px 18px rgba(31, 45, 61, 0.06);
    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease;
}

.cc-match-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 10px 26px rgba(31, 45, 61, 0.09);
}


/* =========================================================
   MATCH HEADER
   ========================================================= */

.cc-match-card-header {
    padding: 20px 22px;
    border-bottom: 1px solid #edf0f4;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
}

.cc-student-profile {
    display: flex;
    align-items: center;
    gap: 13px;
}

.cc-student-avatar {
    width: 48px;
    height: 48px;
    min-width: 48px;
    border-radius: 50%;
    background: #eaf3fc;
    color: #1f5d9b;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 18px;
    font-weight: 700;
}

.cc-student-name {
    margin: 0 0 5px;
    color: #243b53;
    font-size: 17px;
    font-weight: 700;
}

.cc-score {
    color: #5c6b7a;
    font-size: 12px;
    font-weight: 500;
}

.cc-match-badge {
    padding: 7px 12px;
    border-radius: 20px;
    background: #edf8f2;
    color: #19734a;
    font-size: 12px;
    font-weight: 700;
    white-space: nowrap;
}


/* =========================================================
   MATCH BODY
   ========================================================= */

.cc-match-card-body {
    padding: 22px;
}

.cc-info-block {
    margin-bottom: 18px;
}

.cc-info-label {
    margin-bottom: 6px;
    color: #7b8794;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.7px;
    text-transform: uppercase;
}

.cc-skills-text {
    color: #344054;
    font-size: 14px;
    line-height: 1.55;
    word-break: break-word;
}


/* =========================================================
   MATCHING SKILLS
   ========================================================= */

.cc-match-skills {
    display: flex;
    flex-wrap: wrap;
    gap: 7px;
}

.cc-skill {
    padding: 6px 10px;
    border-radius: 18px;
    background: #edf5ff;
    color: #1f5d9b;
    font-size: 12px;
    font-weight: 600;
}


/* =========================================================
   REQUEST ACTION
   ========================================================= */

.cc-request-action {
    margin-top: 8px;
    padding-top: 18px;
    border-top: 1px solid #edf0f4;
    display: flex;
    justify-content: flex-end;
}


/* =========================================================
   NO MATCH
   ========================================================= */

.cc-no-match-card {
    width: 100%;
    max-width: 1180px;
    margin: 0 auto;
    padding: 50px 30px;
    text-align: center;
    background: #ffffff;
    border: 1px solid #e5eaf1;
    border-radius: 16px;
    box-shadow: 0 5px 18px rgba(31, 45, 61, 0.05);
}

.cc-no-match-icon {
    width: 58px;
    height: 58px;
    margin: 0 auto 15px;
    border-radius: 50%;
    background: #f1f4f8;
    color: #7b8794;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 26px;
}

.cc-no-match-card h3 {
    margin: 0;
    color: #344054;
    font-size: 19px;
}

.cc-no-match-card p {
    max-width: 500px;
    margin: 8px auto 0;
    color: #7b8794;
    font-size: 14px;
    line-height: 1.6;
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 768px) {

    .cc-teammate-page {
        padding: 18px;
    }

    .cc-teammate-hero {
        padding: 24px;
        gap: 15px;
    }

    .cc-hero-icon {
        width: 50px;
        height: 50px;
        min-width: 50px;
        font-size: 24px;
    }

    .cc-hero-content h1 {
        font-size: 24px;
    }

    .cc-selection-card {
        padding: 21px;
    }

    .cc-results-header {
        align-items: flex-start;
        flex-direction: column;
    }

    .cc-match-card-header {
        align-items: flex-start;
        flex-direction: column;
    }

    .cc-request-action {
        justify-content: stretch;
    }

    .cc-request-action .cc-send-request-btn {
        width: 100%;
    }

}


@media (max-width: 480px) {

    .cc-teammate-page {
        padding: 12px;
    }

    .cc-teammate-hero {
        padding: 20px;
        border-radius: 14px;
    }

    .cc-hero-content h1 {
        font-size: 21px;
    }

    .cc-hero-content p {
        font-size: 13px;
    }

    .cc-selection-card {
        padding: 17px;
    }

    .cc-selection-header {
        align-items: flex-start;
    }

    .cc-match-card-body {
        padding: 17px;
    }

    .cc-match-card-header {
        padding: 17px;
    }

    .cc-match-badge {
        align-self: flex-start;
    }

}

sp_widget.script:
(function() {

    data.matches = [];

    data.events = [];

    data.message = '';

    data.selectedEventName = '';


    var currentUser =
        gs.getUserID();


    if (!currentUser) {

        data.message =
            'Please log in to use Find Teammates.';

        return;

    }


    /* =========================================
       LOAD VERIFIED EVENTS
       ========================================= */

    var eventGR =
        new GlideRecord(
            'x_snc_campus_con_0_events'
        );

    eventGR.addQuery(
        'verification_status',
        'verified'
    );

    eventGR.orderBy(
        'event_date'
    );

    eventGR.query();


    while (eventGR.next()) {

        data.events.push({

            sys_id:
                eventGR.getUniqueValue(),

            event_name:
                eventGR.getDisplayValue(
                    'event_name'
                ) ||
                eventGR.getValue(
                    'event_name'
                )

        });

    }


    /* =========================================
       FIND MATCHES
       ========================================= */

    if (
        input &&
        input.action == 'find_matches'
    ) {

        var selectedStudent =
            String(
                input.selectedStudent || ''
            ).trim();

        var selectedEvent =
            String(
                input.selectedEvent || ''
            ).trim();


        if (!selectedStudent) {

            data.message =
                'Please enter your name.';

            return;

        }


        if (!selectedEvent) {

            data.message =
                'Please select an event.';

            return;

        }


        /* GET EVENT */

        var selectedEventGR =
            new GlideRecord(
                'x_snc_campus_con_0_events'
            );


        if (
            !selectedEventGR.get(
                selectedEvent
            )
        ) {

            data.message =
                'Selected event was not found.';

            return;

        }


        data.selectedEventName =
            selectedEventGR.getDisplayValue(
                'event_name'
            );


        /* =====================================
           FIND CURRENT STUDENT PROFILE
           ===================================== */

        var currentStudentProfile =
            new GlideRecord(
                'x_snc_campus_con_0_student_profile'
            );


        currentStudentProfile.addQuery(
            'student.name',
            selectedStudent
        );

        currentStudentProfile.setLimit(1);

        currentStudentProfile.query();


        if (!currentStudentProfile.next()) {

            data.message =
                'Student profile was not found.';

            return;

        }


        var currentStudentId =
            currentStudentProfile.getUniqueValue();


        var currentSkills =
            String(
                currentStudentProfile.getValue(
                    'skills'
                ) || ''
            ).toLowerCase();


        if (!currentSkills) {

            data.message =
                'No skills are available for this student.';

            return;

        }


        /* =====================================
           CONVERT CURRENT STUDENT SKILLS
           ===================================== */

        var currentSkillArray =
            currentSkills
                .split(',')
                .map(function(skill) {

                    return skill.trim();

                })
                .filter(function(skill) {

                    return skill !== '';

                });


        /* =====================================
           FIND OTHER STUDENTS
           ===================================== */

        var studentGR =
            new GlideRecord(
                'x_snc_campus_con_0_student_profile'
            );


        studentGR.addQuery(
            'sys_id',
            '!=',
            currentStudentId
        );

        studentGR.query();


        while (studentGR.next()) {


            var otherSkills =
                String(
                    studentGR.getValue(
                        'skills'
                    ) || ''
                ).toLowerCase();


            if (!otherSkills) {
                continue;
            }


            var otherSkillArray =
                otherSkills
                    .split(',')
                    .map(function(skill) {

                        return skill.trim();

                    })
                    .filter(function(skill) {

                        return skill !== '';

                    });


            var overlapSkills = [];


            for (
                var i = 0;
                i < currentSkillArray.length;
                i++
            ) {

                for (
                    var j = 0;
                    j < otherSkillArray.length;
                    j++
                ) {

                    if (
                        currentSkillArray[i] ===
                        otherSkillArray[j]
                    ) {

                        if (
                            overlapSkills.indexOf(
                                currentSkillArray[i]
                            ) === -1
                        ) {

                            overlapSkills.push(
                                currentSkillArray[i]
                            );

                        }

                    }

                }

            }


            if (
                overlapSkills.length === 0
            ) {

                continue;

            }


            var studentUserId =
                studentGR.getValue(
                    'student'
                );


            var studentName =
                studentGR.getDisplayValue(
                    'student'
                );


            data.matches.push({

                studentId:
                    studentUserId,

                studentName:
                    studentName,

                skills:
                    studentGR.getValue(
                        'skills'
                    ) || '',

                collegeName:
                    studentGR.getValue(
                        'college_name'
                    ) || '',

                location:
                    studentGR.getValue(
                        'location'
                    ) || '',

                matchCount:
                    overlapSkills.length,

                overlapSkillsArray:
                    overlapSkills

            });

        }


        if (
            data.matches.length === 0
        ) {

            data.message =
                'No students with matching skills were found.';

        }


        return;

    }


    /* =========================================
       SEND TEAM REQUEST
       ========================================= */

    if (
        input &&
        input.action == 'send_team_request'
    ) {


        var receiverStudent =
            String(
                input.receiverStudent || ''
            ).trim();


        var eventId =
            String(
                input.eventId || ''
            ).trim();


        if (!receiverStudent) {

            data.message =
                'Receiver student information is missing.';

            data.success = false;

            return;

        }


        if (!eventId) {

            data.message =
                'Event information is missing.';

            data.success = false;

            return;

        }


        /* =====================================
           GET SENDER STUDENT PROFILE
           ===================================== */

        var senderProfile =
            new GlideRecord(
                'x_snc_campus_con_0_student_profile'
            );


        senderProfile.addQuery(
            'student',
            currentUser
        );

        senderProfile.setLimit(1);

        senderProfile.query();


        if (!senderProfile.next()) {

            data.message =
                'Your student profile was not found.';

            data.success = false;

            return;

        }


        var senderStudent =
            senderProfile.getUniqueValue();


        /* =====================================
           VALIDATE RECEIVER
           ===================================== */

        var receiverProfile =
            new GlideRecord(
                'x_snc_campus_con_0_student_profile'
            );


        receiverProfile.addQuery(
            'student',
            receiverStudent
        );

        receiverProfile.setLimit(1);

        receiverProfile.query();


        if (!receiverProfile.next()) {

            data.message =
                'Receiver student profile was not found.';

            data.success = false;

            return;

        }


        /* =====================================
           VALIDATE EVENT
           ===================================== */

        var event =
            new GlideRecord(
                'x_snc_campus_con_0_events'
            );


        if (!event.get(eventId)) {

            data.message =
                'Selected event was not found.';

            data.success = false;

            return;

        }


        var eventStatus =
            String(
                event.getValue(
                    'verification_status'
                ) || ''
            ).toLowerCase();


        if (
            eventStatus != 'verified'
        ) {

            data.message =
                'Only verified events can be used for team requests.';

            data.success = false;

            return;

        }


        var eventName =
            event.getDisplayValue(
                'event_name'
            );


        /* =====================================
           FIND EXISTING OPEN TEAM
           FOR THIS SENDER + EVENT
           ===================================== */

        var team =
            new GlideRecord(
                'x_snc_campus_con_0_teams'
            );


        team.addQuery(
            'team_lead',
            currentUser
        );

        team.addQuery(
            'event',
            eventId
        );

        team.addQuery(
            'formation_type',
            'skill-matched'
        );

        team.addQuery(
            'status',
            'open'
        );

        team.setLimit(1);

        team.query();


        if (!team.next()) {


            /* =================================
               CREATE NEW TEAM
               ================================= */

            team =
                new GlideRecord(
                    'x_snc_campus_con_0_teams'
                );


            team.initialize();


            var senderName =
                senderProfile.getDisplayValue(
                    'student'
                );


            team.setValue(
                'team_name',
                'Skill Match Team - ' +
                senderName
            );


            team.setValue(
                'team_lead',
                currentUser
            );


            team.setValue(
                'event',
                eventId
            );


            team.setValue(
                'formation_type',
                'skill-matched'
            );


            team.setValue(
                'status',
                'open'
            );


            var teamId =
                team.insert();


            if (!teamId) {

                data.message =
                    'Unable to create the team.';

                data.success = false;

                return;

            }

        }


        var teamId =
            team.getUniqueValue();


        /* =====================================
           CHECK WHETHER REQUEST ALREADY EXISTS
           ===================================== */

        var existingMember =
            new GlideRecord(
                'x_snc_campus_con_0_team_members'
            );


        existingMember.addQuery(
            'team',
            teamId
        );

        existingMember.addQuery(
            'student',
            receiverStudent
        );


        existingMember.query();


        if (existingMember.next()) {

            var existingStatus =
                String(
                    existingMember.getValue(
                        'join_status'
                    ) || ''
                );


            if (
                existingStatus == 'requested'
            ) {

                data.message =
                    'A team request has already been sent to this student.';

                data.success = false;

                return;

            }


            if (
                existingStatus == 'accepted'
            ) {

                data.message =
                    'This student is already a member of your team.';

                data.success = false;

                return;

            }

        }


        /* =====================================
           CHECK TEAM MEMBER COUNT
           ===================================== */

        var acceptedMembers =
            new GlideRecord(
                'x_snc_campus_con_0_team_members'
            );


        acceptedMembers.addQuery(
            'team',
            teamId
        );

        acceptedMembers.addQuery(
            'join_status',
            'accepted'
        );

        acceptedMembers.query();


        var acceptedCount = 0;


        while (
            acceptedMembers.next()
        ) {

            acceptedCount++;

        }


        if (
            acceptedCount >= 5
        ) {

            data.message =
                'This team already has the maximum number of members.';

            data.success = false;

            return;

        }


        /* =====================================
           CREATE TEAM MEMBER REQUEST
           ===================================== */

        var member =
            new GlideRecord(
                'x_snc_campus_con_0_team_members'
            );


        member.initialize();


        member.setValue(
            'team',
            teamId
        );


        member.setValue(
            'student',
            receiverStudent
        );


        /*
         * IMPORTANT:
         * My Team Requests searches exactly
         * for "Requested".
         */

        member.setValue(
            'join_status',
            'requested'
        );


        member.setValue(
            'commitment_confirmed',
            true
        );


        var memberId =
            member.insert();


        if (!memberId) {

            data.message =
                'Unable to create the team request.';

            data.success = false;

            return;

        }


        data.success = true;

        data.eventName =
            eventName;

        data.message =
            'Team request sent successfully.';

        return;

    }


})();
